USE wildtrail_db;
ALTER TABLE vehicles ADD COLUMN photo VARCHAR(255) NULL AFTER capacity, ADD COLUMN safari_type ENUM('open','covered','premium') DEFAULT 'open' AFTER photo, ADD COLUMN amenities VARCHAR(500) NULL AFTER safari_type, ADD COLUMN base_price DECIMAL(10,2) DEFAULT 18000 AFTER amenities;
ALTER TABLE guide_profiles ADD COLUMN profile_photo VARCHAR(255) NULL AFTER license_doc, ADD COLUMN specialties VARCHAR(255) NULL AFTER languages, ADD COLUMN experience_years INT DEFAULT 0 AFTER specialties, ADD COLUMN guide_fee DECIMAL(10,2) DEFAULT 6000 AFTER experience_years;
CREATE TABLE guide_availability(id INT AUTO_INCREMENT PRIMARY KEY,guide_id INT NOT NULL,available_date DATE NOT NULL,slot ENUM('dawn','morning','afternoon') NOT NULL,is_available TINYINT(1) DEFAULT 1,UNIQUE(guide_id,available_date,slot),FOREIGN KEY(guide_id) REFERENCES users(id) ON DELETE CASCADE);
ALTER TABLE bookings ADD COLUMN entry_fee_component DECIMAL(10,2) DEFAULT 0 AFTER payment_ref, ADD COLUMN vehicle_fee_component DECIMAL(10,2) DEFAULT 0 AFTER entry_fee_component, ADD COLUMN guide_fee_component DECIMAL(10,2) DEFAULT 0 AFTER vehicle_fee_component, ADD COLUMN preferred_language VARCHAR(60) NULL AFTER guide_fee_component, ADD COLUMN pickup_location VARCHAR(180) NULL AFTER preferred_language, ADD COLUMN contact_phone VARCHAR(30) NULL AFTER pickup_location, ADD COLUMN cancellation_reason VARCHAR(255) NULL AFTER special_notes;
ALTER TABLE reviews CHANGE COLUMN rating overall_rating TINYINT NOT NULL, ADD COLUMN guide_rating TINYINT NULL AFTER visitor_id, ADD COLUMN vehicle_rating TINYINT NULL AFTER guide_rating, ADD COLUMN driver_rating TINYINT NULL AFTER vehicle_rating;
